using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using FutebolDeDiscos;using TMPro;
public static class RootHarness {
static int checks;static string caseName;
static void Check(bool condition,string message){checks++;if(!condition)throw new Exception(caseName+": "+message+" Errors: "+string.Join(" | ",Debug.Errors.ToArray()));}
static void Call(object obj,string name){if(obj==null)return;var m=obj.GetType().GetMethod(name,BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance);if(m==null)return;try{m.Invoke(obj,null);}catch(TargetInvocationException e){throw e.InnerException;}}
static void Reset(){foreach(var go in GameObject.All.Where(g=>g.transform.parent==null&&!g.destroyed).ToArray())UnityEngine.Object.Destroy(go);GameObject.All.Clear();Scheduler.Reset();Time.captureDeltaTime=0;Debug.Errors.Clear();Debug.Messages.Clear();Debug.Warnings.Clear();}
static List<TeamData> Teams(int n){return Enumerable.Range(1,n).Select(i=>{var t=ScriptableObject.CreateInstance<TeamData>();t.name="team_"+i;t.nomeEquipe="Team "+i;t.sigla="T"+i;t.corPrincipal=i%2==0?Color.red:Color.blue;t.elenco.Add(new JogadorDados{nomeJogador="Player "+i});return t;}).ToList();}
sealed class RootCase {
public GameObject go;public ProjetoFutebolDiscos config;public TournamentManager manager;public LigaCampeonato liga;public MataMataCampeonato mata;public UniversalUI ui;public PartidaDiscos engine;public ClassificacaoUI tabela;
public RootCase(string season,FormatoDiscos format,List<TeamData> teams,int rounds=2,bool one=false,bool start=true){go=new GameObject("Competition");go.SetActive(false);config=go.AddComponent<ProjetoFutebolDiscos>();manager=go.AddComponent<TournamentManager>();liga=go.AddComponent<LigaCampeonato>();mata=go.AddComponent<MataMataCampeonato>();ui=go.AddComponent<UniversalUI>();tabela=go.AddComponent<ClassificacaoUI>();go.AddComponent<AberturaJogoUI>();go.AddComponent<GoalBannerUI>();go.AddComponent<ChaveamentoUI>();engine=go.AddComponent<PartidaDiscos>();config.competicaoId="runtime_disc_test";config.temporadaId=season;config.formato=format;config.quantidadeTimes=teams.Count;config.quantidadeRodadas=rounds;config.participantes=teams;config.duracaoPartida=.2f;config.tempoAbertura=config.tempoFotos=config.tempoTransicaoFotos=config.tempoTabela=config.intervaloEntrePartidas=0;config.umaRodadaOuFasePorPlay=one;config.tema=ScriptableObject.CreateInstance<TemaCompeticao>();config.tema.fonteTexto=config.tema.fonteTitulo=TMP_Settings.defaultFontAsset;go.SetActive(true);go.GetComponent<GoalBannerUI>().tempoDeExibicao=.02f;go.GetComponent<GoalBannerUI>().intervaloEntreBanners=0;if(start)Start();}
public void Start(){Call(config,"Start");Call(manager,"Start");}
public void Frame(bool golden=true){Time.unscaledDeltaTime=.1f;Time.deltaTime=.1f*Time.timeScale;Time.captureDeltaTime=.1f;Call(config,"Update");Call(engine,"Update");Call(engine,"FixedUpdate");Call(ui,"Update");if(golden&&ui.EmProrrogacao&&ui.partidaEmAndamento&&engine.EmAndamento){engine.Bola.Corpo.position=new Vector2(CampoDiscos.MeioComprimento+config.tamanhoBola*.5f+.1f,0);engine.NotificarGol(false);}Scheduler.Tick(.1f);}
public void Until(Func<bool> predicate,int frames=1500,bool golden=true){for(int i=0;i<frames&&!predicate();i++)Frame(golden);Check(predicate(),"expected progression gate reached within "+frames+" frames; status="+config.situacao);}
public string ResultPath{get{return Path.Combine(Application.persistentDataPath,config.formato==FormatoDiscos.Liga?"Ligas":"MataMata",config.competicaoId,config.temporadaId,config.formato==FormatoDiscos.Liga?"temporada.json":"torneio.json");}}
public string MetadataPath{get{return Path.Combine(config.PastaDaTemporada,"configuracao_discos.json");}}
}
static void AutomaticLeague(){caseName="automatic real league";var t=Teams(4);var r=new RootCase("automatic",FormatoDiscos.Liga,t,3);Check(r.config.Preparado&&r.manager.LigaPreparada&&!r.manager.iniciarAutomaticamente,"central Start prepares real CSV/store with no duplicate TM auto-start");Check(File.Exists(r.MetadataPath)&&File.Exists(r.ResultPath)&&r.config.SementeEfetiva>0,"new automatic seed and draft state persist before match begins");int seed=r.config.SementeEfetiva;string metadata=File.ReadAllText(r.MetadataPath);r.Until(()=>r.config.CompeticaoConcluida);Check(r.manager.rodadaDesejada==3&&r.manager.EncerramentoRodadaConcluido,"three real rounds advance only after closing standings");var table=r.liga.ObterClassificacao(true);Check(table.Count==4&&table.All(l=>l.P==3&&l.D==3&&l.PTS==3),"four-team league finishes six genuine draws and exact final points");var saved=JsonUtility.FromJson<LigaCampeonato.Dados>(File.ReadAllText(r.ResultPath));Check(saved.rodadas.Count==3&&saved.rodadas.All(x=>x.confirmada&&x.jogos.All(j=>j.registrado)),"all round confirmations and per-game results are durable");Check(Debug.Errors.Count==0,"automatic full season emits no integration errors");Reset();var reload=new RootCase("automatic",FormatoDiscos.Liga,t,3,false,false);reload.liga.rodadaParaExportar=1;reload.Start();reload.Until(()=>reload.tabela.UltimaExibicaoConcluida);Check(reload.config.CompeticaoConcluida&&reload.engine.Bola==null,"completed league reload shows standings without replaying any game");Check(reload.config.SementeEfetiva==seed&&File.ReadAllText(reload.MetadataPath)==metadata,"reload preserves exact season identity and automatic seed");Check(reload.liga.rodadaParaExportar==1&&((GameObject)typeof(ClassificacaoUI).GetField("raiz",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(reload.tabela)).GetComponentsInChildren<TextMeshProUGUI>(true).Any(x=>x.text=="ROUND 3  ·  MATCH DATA"),"final standings ignore an old export selector then restore it");Reset();}
static void ResumeDraft(){caseName="draft resume and isolated seasons";var t=Teams(4);var r=new RootCase("partial",FormatoDiscos.Liga,t,2);r.Until(()=>File.Exists(r.ResultPath)&&JsonUtility.FromJson<LigaCampeonato.Dados>(File.ReadAllText(r.ResultPath)).rodadas[0].jogos.Count(j=>j.registrado)==1);int seed=r.config.SementeEfetiva;string metadata=File.ReadAllText(r.MetadataPath);Reset();var resumed=new RootCase("partial",FormatoDiscos.Liga,t,2);Check(resumed.manager.rodadaDesejada==1&&resumed.manager.rodadaAtual.Count(c=>c.concluido&&c.pontosRegistrados)==1,"fresh Play recovers completed match in pending round");resumed.Until(()=>resumed.config.CompeticaoConcluida);Check(resumed.liga.ObterClassificacao(true).All(x=>x.P==2&&x.PTS==2),"resume never repeats first saved result or points");Check(resumed.config.SementeEfetiva==seed&&File.ReadAllText(resumed.MetadataPath)==metadata,"draft resume keeps calendar seed unchanged");Reset();var other=new RootCase("independent",FormatoDiscos.Liga,t,2);Check(other.manager.rodadaDesejada==1&&other.manager.rodadaAtual.All(c=>!c.concluido),"separate season never inherits another season standings");Reset();}
static void OneRound(){caseName="one round per Play";var t=Teams(4);var r=new RootCase("one_round",FormatoDiscos.Liga,t,2,true);r.Until(()=>r.manager.EncerramentoRodadaConcluido);for(int i=0;i<10;i++)r.Frame();Check(r.manager.rodadaDesejada==1&&r.config.Preparado&&!r.config.CompeticaoConcluida,"optional round stop waits with saved standings");var saved=JsonUtility.FromJson<LigaCampeonato.Dados>(File.ReadAllText(r.ResultPath));Check(saved.rodadas.Count==1&&saved.rodadas[0].confirmada,"round stop still confirms the completed round automatically");r.config.ContinuarNoPlay();Check(r.manager.rodadaDesejada==2&&r.manager.LigaPreparada,"continue opens precisely next round");r.Until(()=>r.config.CompeticaoConcluida);Check(r.liga.ObterClassificacao(true).All(x=>x.P==2),"continued season reaches exact expected match counts");Reset();}
static void Knockout(){caseName="real knockout flow";var t=Teams(4);var r=new RootCase("knockout",FormatoDiscos.MataMata,t);Check(r.config.Preparado&&!r.manager.modoLiga&&r.ui.ativarGoldenGoal,"central knockout binds original bracket with golden-goal rule");r.Until(()=>r.config.CompeticaoConcluida);Check(r.mata.Concluido&&r.mata.EstadoAtual.fases.Sum(f=>f.partidas.Count(p=>p.concluida&&!p.bye))==3,"real physical goal callbacks decide both semifinals and final");Check(r.mata.EstadoAtual.fases.SelectMany(f=>f.partidas).All(p=>p.golsA==1&&p.golsB==0),"knockout uses genuine sudden-death scores instead of synthetic tie-break");int seed=r.config.SementeEfetiva;Reset();var reload=new RootCase("knockout",FormatoDiscos.MataMata,t);reload.Until(()=>reload.config.CompeticaoConcluida);Check(reload.mata.Concluido&&reload.engine.Bola==null&&reload.config.SementeEfetiva==seed,"completed knockout reload never replays final and preserves seed");Reset();}
static void KnockoutRetry(){caseName="root knockout write-failure recovery";var t=Teams(2);var r=new RootCase("retry_knockout",FormatoDiscos.MataMata,t);r.Until(()=>r.ui.EmProrrogacao,1500,false);string dir=Path.GetDirectoryName(r.ResultPath),hold=dir+"_hold";Directory.Move(dir,hold);File.WriteAllText(dir,"temporary-obstruction");r.engine.Bola.Corpo.position=new Vector2(11.5f,0);r.engine.NotificarGol(false);r.Until(()=>r.manager.SalvamentoPendente,100,false);for(int i=0;i<4;i++)r.Frame(false);Check(r.config.Preparado&&r.manager.enabled&&!r.config.CompeticaoConcluida&&!r.engine.EmAndamento,"failed KO save pauses safely while preserving public retry path");File.Delete(dir);Directory.Move(hold,dir);r.config.ContinuarNoPlay();r.Until(()=>r.config.CompeticaoConcluida,100);Check(!r.manager.SalvamentoPendente&&r.mata.Concluido&&r.mata.EstadoAtual.fases[0].partidas[0].golsA==1,"root continue commits pending golden goal exactly once and awards champion");Reset();}
static void GuardsAndDisable(){caseName="saved configuration guard and component lifecycle";var t=Teams(2);var r=new RootCase("guard",FormatoDiscos.Liga,t,1);string metadata=File.ReadAllText(r.MetadataPath),results=File.ReadAllText(r.ResultPath);Reset();var changed=new RootCase("guard",FormatoDiscos.Liga,t,1,false,false);changed.config.tamanhoDisco=1.2f;changed.Start();Check(!changed.config.Preparado&&!changed.manager.enabled&&changed.config.ultimoErro.Contains("difere"),"changing fixed season physics pauses before overwriting original results");Check(File.ReadAllText(changed.MetadataPath)==metadata&&File.ReadAllText(changed.ResultPath)==results,"guard preserves exact metadata and result bytes");Reset();var active=new RootCase("disable",FormatoDiscos.Liga,t,2);active.Until(()=>active.ui.partidaEmAndamento,500,false);active.config.enabled=false;Check(!active.config.Preparado&&!active.ui.partidaEmAndamento&&!active.engine.EmAndamento&&!active.manager.enabled,"disabling root freezes match and prevents TM coroutine continuation");for(int i=0;i<20;i++)active.Frame(false);Check(!active.engine.EmAndamento,"disabled root does not resurrect match through scheduled invocation");Reset();}
public static void Main(){string dir=Path.Combine(Path.GetTempPath(),"disc-root-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);Application.persistentDataPath=dir;try{Reset();AutomaticLeague();ResumeDraft();OneRound();Knockout();KnockoutRetry();GuardsAndDisable();Console.WriteLine("PASS "+checks+" real controller + original tournament/UI/physics/filesystem integration assertions.");Console.WriteLine("PASS automatic round progression, single-round continuation, real golden goals, KO save retry, resume, final tables, seed identity, configuration guards and lifecycle.");}finally{Reset();Directory.Delete(dir,true);}}
}
